#include <iostream>
#include <vector>
#include <map>
#include <cassert>
#include <algorithm>
using namespace std;

const int MOD = 1000000007;

class ModInt {
public:
    int value;

    ModInt(long long v = 0) {
        v %= MOD;
        if (v < 0) v += MOD;
        value = static_cast<int>(v);
    }

    static int mod_inverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return value; }

    ModInt& operator+=(const ModInt& other) {
        value += other.value;
        if (value >= MOD) value -= MOD;
        return *this;
    }

    ModInt& operator-=(const ModInt& other) {
        value -= other.value;
        if (value < 0) value += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
        return static_cast<unsigned>(x % m);
    }

    ModInt& operator*=(const ModInt& other) {
        value = fast_mod(static_cast<uint64_t>(value) * other.value);
        return *this;
    }

    ModInt& operator/=(const ModInt& other) {
        return *this *= other.inverse();
    }

    friend ModInt operator+(const ModInt& a, const ModInt& b) { return ModInt(a) += b; }
    friend ModInt operator-(const ModInt& a, const ModInt& b) { return ModInt(a) -= b; }
    friend ModInt operator*(const ModInt& a, const ModInt& b) { return ModInt(a) *= b; }
    friend ModInt operator/(const ModInt& a, const ModInt& b) { return ModInt(a) /= b; }

    ModInt& operator++() {
        value = (value == MOD - 1) ? 0 : value + 1;
        return *this;
    }

    ModInt& operator--() {
        value = (value == 0) ? MOD - 1 : value - 1;
        return *this;
    }

    ModInt operator++(int) { ModInt tmp = *this; ++*this; return tmp; }
    ModInt operator--(int) { ModInt tmp = *this; --*this; return tmp; }

    ModInt operator-() const { return value ? MOD - value : 0; }

    bool operator==(const ModInt& other) const { return value == other.value; }
    bool operator!=(const ModInt& other) const { return value != other.value; }

    ModInt inverse() const { return mod_inverse(value); }

    ModInt power(long long exp) const {
        assert(exp >= 0);
        ModInt base = *this, result = 1;
        while (exp > 0) {
            if (exp & 1) result *= base;
            base *= base;
            exp >>= 1;
        }
        return result;
    }
};

const int MAX_N = 7;
int n;
ModInt probabilities[MAX_N][MAX_N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int p;
            cin >> p;
            probabilities[i][j] = ModInt(p) / ModInt(100);
        }
    }

    vector<vector<int>> masks_by_population(MAX_N + 1);
    vector<int> index_map(1 << n, -1);

    for (int mask = 0; mask < (1 << n); ++mask) {
        int popcount = __builtin_popcount(mask);
        index_map[mask] = masks_by_population[popcount].size();
        masks_by_population[popcount].push_back(mask);
    }

    map<long long, ModInt> current_states;
    current_states[1LL << index_map[0]] = ModInt(1);

    for (int step = 0; step < n; ++step) {
        map<long long, ModInt> next_states;

        for (int current_mask = 0; current_mask < (1 << n); ++current_mask) {
            ModInt product = ModInt(1);
            for (int j = 0; j < n; ++j) {
                if ((current_mask >> j) & 1) {
                    product *= probabilities[step][j];
                } else {
                    product += ModInt(1) - probabilities[step][j];
                }
            }

            for (const auto& [state_key, state_prob] : current_states) {
                long long state = state_key;
                ModInt prob = state_prob;

                long long new_state = 0;

                for (int mask : masks_by_population[step]) {
                    if ((state >> index_map[mask]) & 1) {
                        for (int i = 0; i < n; ++i) {
                            if (((current_mask >> i) & 1) && !((mask >> i) & 1)) {
                                new_state |= 1LL << index_map[mask | (1 << i)];
                            }
                        }
                    }
                }

                next_states[new_state] += prob * product;
            }
        }

        current_states = move(next_states);
    }

    ModInt result = ModInt(0);
    long long full_set = (1LL << n) - 1;

    for (const auto& [state_key, state_prob] : current_states) {
        if ((state_key >> index_map[full_set]) & 1) {
            result += state_prob;
        }
    }

    cout << (int)result << '\n';
    return 0;
}
